import { ApplicationDependencies } from '../../src/orchestrator/dependencies'
import type { NowConfig, Logger } from '@servicenow/sdk-build-core'

describe('ApplicationDependencies.configurationToScopedFetch', () => {
    describe('Flow dependencies - scope-first structure', () => {
        it('should parse actions with single scope', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    'automation.actions': ['action1', 'action2'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)
            expect(result.size).toBe(1)
            expect(result.get('global')).toEqual([
                {
                    table: 'sys_hub_action_type_definition',
                    ids: ['action1', 'action2'],
                    field: 'sys_id',
                },
            ])
        })

        it('should parse actions with multiple scopes', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    'automation.actions': ['action1'],
                },
                x_custom: {
                    'automation.actions': ['action2', 'action3'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(2)
            expect(result.get('global')).toContainEqual({
                table: 'sys_hub_action_type_definition',
                ids: ['action1'],
                field: 'sys_id',
            })
            expect(result.get('x_custom')).toContainEqual({
                table: 'sys_hub_action_type_definition',
                ids: ['action2', 'action3'],
                field: 'sys_id',
            })
        })

        it('should parse triggers', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    'automation.triggers': ['trigger1'],
                },
                x_app: {
                    'automation.triggers': ['trigger2'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(2)
            expect(result.get('global')?.[0].table).toBe('sys_hub_trigger_definition')
            expect(result.get('x_app')?.[0].table).toBe('sys_hub_trigger_definition')
        })

        it('should parse subflows', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                sn_sow_inc: {
                    'automation.subflows': ['subflow1'],
                },
                global: {
                    'automation.subflows': ['subflow2'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(2)
            expect(result.get('sn_sow_inc')?.[0].table).toBe('sys_hub_flow')
            expect(result.get('global')?.[0].table).toBe('sys_hub_flow')
        })

        it('should handle wildcard for actions', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                x_custom: {
                    'automation.actions': '*',
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.get('x_custom')?.[0].ids).toEqual(['*'])
        })

        it('should parse multiple flow types across scopes', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    'automation.actions': ['action1'],
                },
                x_app: {
                    'automation.triggers': ['trigger1'],
                },
                sn_sow_inc: {
                    'automation.subflows': ['subflow1'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(3)
            expect(result.get('global')?.[0].table).toBe('sys_hub_action_type_definition')
            expect(result.get('x_app')?.[0].table).toBe('sys_hub_trigger_definition')
            expect(result.get('sn_sow_inc')?.[0].table).toBe('sys_hub_flow')
        })
    })

    describe('Core dependencies - scope-first structure', () => {
        it('should parse tables with single scope', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    tables: ['incident', 'problem'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(1)
            expect(result.get('global')).toEqual([
                {
                    table: 'sys_db_object',
                    ids: ['incident', 'problem'],
                    field: 'name',
                },
            ])
        })

        it('should parse tables with multiple scopes', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    tables: ['incident'],
                },
                x_custom: {
                    tables: ['custom_table'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(2)
            expect(result.get('global')?.[0].field).toBe('name')
            expect(result.get('x_custom')?.[0].field).toBe('name')
        })

        it('should handle wildcard for tables', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                x_custom: {
                    tables: '*',
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.get('x_custom')?.[0].ids).toEqual(['*'])
        })

        it('should parse generic tables by sys_id', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    sys_security_acl: ['acl1', 'acl2'],
                },
                x_app: {
                    sys_security_acl: ['acl3'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(2)
            expect(result.get('global')?.[0].table).toBe('sys_security_acl')
            expect(result.get('x_app')?.[0].table).toBe('sys_security_acl')
        })
    })

    describe('Mixed dependencies', () => {
        it('should parse both tables and flow dependencies in same scope', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    tables: ['incident'],
                    'automation.actions': ['action1'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(1)
            const globalFetches = result.get('global')
            expect(globalFetches).toHaveLength(2)
            expect(globalFetches?.map((f) => f.table)).toContain('sys_db_object')
            expect(globalFetches?.map((f) => f.table)).toContain('sys_hub_action_type_definition')
        })

        it('should handle complex multi-scope configuration', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    tables: ['incident', 'problem'],
                    sys_security_acl: ['acl1'],
                    'automation.actions': ['action1'],
                },
                x_app1: {
                    tables: ['custom1'],
                    'automation.triggers': ['trigger1'],
                },
                x_app2: {
                    'automation.actions': ['action2'],
                },
                sn_sow_inc: {
                    'automation.subflows': ['subflow1'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(4)
            expect(result.has('global')).toBe(true)
            expect(result.has('x_app1')).toBe(true)
            expect(result.has('x_app2')).toBe(true)
            expect(result.has('sn_sow_inc')).toBe(true)
            expect(result.get('global')?.length).toBe(3)
            expect(result.get('x_app1')?.length).toBe(2)
        })
    })

    describe('Empty configurations', () => {
        it('should handle empty config', () => {
            const config: NonNullable<NowConfig['dependencies']> = {}

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(0)
        })

        it('should handle empty scope', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {},
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)

            expect(result.size).toBe(0)
        })
    })

    describe('Wildcard handling', () => {
        it('should handle wildcard string for actions', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    'automation.actions': '*',
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)
            expect(result.get('global')?.[0].ids).toEqual(['*'])
        })

        it('should handle wildcard array for actions', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    'automation.actions': ['*'],
                },
            }

            const result = ApplicationDependencies.configurationToScopedFetch(config)
            expect(result.get('global')?.[0].ids).toEqual(['*'])
        })
    })

    describe('Deprecated applications format (backward compatibility)', () => {
        const mockLogger: Logger = {
            info: jest.fn(),
            warn: jest.fn(),
            error: jest.fn(),
            debug: jest.fn(),
        }

        beforeEach(() => {
            jest.clearAllMocks()
        })

        it('should parse old applications wrapper format with tables', () => {
            const config = {
                applications: {
                    global: {
                        tables: ['cmdb_ci_server'],
                    },
                    sn_ace: {
                        tables: ['sn_ace_app_config'],
                    },
                },
            } as NonNullable<NowConfig['dependencies']>

            const result = ApplicationDependencies.configurationToScopedFetch(config, mockLogger)
            expect(result.size).toBe(2)
            expect(result.get('global')).toEqual([
                {
                    table: 'sys_db_object',
                    ids: ['cmdb_ci_server'],
                    field: 'name',
                },
            ])
            expect(result.get('sn_ace')).toEqual([
                {
                    table: 'sys_db_object',
                    ids: ['sn_ace_app_config'],
                    field: 'name',
                },
            ])
        })

        it('should log deprecation warning when using old format', () => {
            const config = {
                applications: {
                    global: {
                        tables: ['incident'],
                    },
                },
            } as NonNullable<NowConfig['dependencies']>

            ApplicationDependencies.configurationToScopedFetch(config, mockLogger)
            expect(mockLogger.warn).toHaveBeenCalledWith(expect.stringContaining('DEPRECATED'))
            expect(mockLogger.warn).toHaveBeenCalledWith(expect.stringContaining('dependencies.applications'))
        })

        it('should not log deprecation warning for new flat format', () => {
            const config: NonNullable<NowConfig['dependencies']> = {
                global: {
                    tables: ['incident'],
                },
            }

            ApplicationDependencies.configurationToScopedFetch(config, mockLogger)
            expect(mockLogger.warn).not.toHaveBeenCalled()
        })

        it('should handle old format with multiple scopes', () => {
            const config = {
                applications: {
                    global: {
                        tables: ['incident', 'problem'],
                    },
                    x_custom_app: {
                        tables: ['custom_table'],
                    },
                },
            } as NonNullable<NowConfig['dependencies']>

            const result = ApplicationDependencies.configurationToScopedFetch(config, mockLogger)
            expect(result.size).toBe(2)
            expect(result.get('global')?.[0].ids).toEqual(['incident', 'problem'])
            expect(result.get('x_custom_app')?.[0].ids).toEqual(['custom_table'])
        })
    })
})
